In case this is still relevant, and in case a quick-and-dirty fixer is helpful for the upcoming release, here's what just worked for me:  run and then restore `chmod u+x` where needed.

```
from pathlib import Path
import sys

def print_indented(folder, indent):
    print("  "*indent + folder.name, ' - ', oct(folder.stat().st_mode))

global weird
weird = []

def process_path(target_path, level=0):
    target_path.chmod(0o774)    # is a dir: drwx-r-xr-x
    print_indented(target_path, level)
    
    for fpath in target_path.iterdir():
        if fpath.is_dir():
            target_path.chmod(0o774)    # is a dir: drwx-r-xr-x
            process_path(fpath, level+1)
        else:
            try:
                fpath.chmod(0o664)
                print_indented(fpath, level+1)
            except FileNotFoundError:
                weird.append(fpath)



if __name__ == "__main__":
    root = sys.argv[1]
    root = Path(root)     # or Path.home() / Path(root)
    process_path(root)
```

